import{_ as t,a as d,o as a,ai as r}from"./chunks/framework.BbOtTPsL.js";const g=JSON.parse('{"title":"List Orders","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-list-orders","title":"List Orders","description":"Paginated list of all orders across every customer (cursor pagination).","query":"query adminOrders($first: Int) {\\n  adminOrders(first: $first) {\\n    totalCount\\n    pageInfo { hasNextPage endCursor }\\n    edges {\\n      node {\\n        id\\n        incrementId\\n        status\\n        statusLabel\\n        channelName\\n        customerEmail\\n        customerName\\n        grandTotal\\n        formattedGrandTotal\\n        totalQtyOrdered\\n        createdAt\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n    \\"first\\": 10\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminOrders\\": {\\n      \\"totalCount\\": 616,\\n      \\"pageInfo\\": { \\"hasNextPage\\": true, \\"endCursor\\": \\"OQ==\\" },\\n      \\"edges\\": [\\n        {\\n          \\"node\\": {\\n            \\"id\\": 2392,\\n            \\"incrementId\\": \\"2392\\",\\n            \\"status\\": \\"processing\\",\\n            \\"statusLabel\\": \\"Processing\\",\\n            \\"channelName\\": \\"bagisto store\\",\\n            \\"customerEmail\\": \\"admin@example.com\\",\\n            \\"customerName\\": \\"Test User\\",\\n            \\"grandTotal\\": 4000,\\n            \\"formattedGrandTotal\\": \\"$4,000.00\\",\\n            \\"totalQtyOrdered\\": 1,\\n            \\"createdAt\\": \\"2026-05-19 13:13:29\\"\\n          }\\n        }\\n      ]\\n    }\\n  }\\n}\\n"},{"id":"admin-list-orders-filtered","title":"List Orders (filtered)","description":"Filter by status, grand-total range and a date preset.","query":"query adminOrders(\\n  $first: Int\\n  $status: String\\n  $grand_total_from: Float\\n  $grand_total_to: Float\\n  $date_range: String\\n) {\\n  adminOrders(\\n    first: $first\\n    status: $status\\n    grand_total_from: $grand_total_from\\n    grand_total_to: $grand_total_to\\n    date_range: $date_range\\n  ) {\\n    totalCount\\n    edges {\\n      node {\\n        id\\n        incrementId\\n        status\\n        grandTotal\\n        createdAt\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n    \\"first\\": 10,\\n    \\"status\\": \\"processing\\",\\n    \\"grand_total_from\\": 100,\\n    \\"grand_total_to\\": 5000,\\n    \\"date_range\\": \\"this_month\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminOrders\\": {\\n      \\"totalCount\\": 12,\\n      \\"edges\\": [\\n        {\\n          \\"node\\": {\\n            \\"id\\": 2392,\\n            \\"incrementId\\": \\"2392\\",\\n            \\"status\\": \\"processing\\",\\n            \\"grandTotal\\": 4000,\\n            \\"createdAt\\": \\"2026-05-19 13:13:29\\"\\n          }\\n        }\\n      ]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/orders/list-orders.md","filePath":"api/graphql-api/admin/sales/orders/list-orders.md","lastUpdated":1781099665000}'),o={name:"api/graphql-api/admin/sales/orders/list-orders.md"};function n(s,e,i,c,l,m){return a(),d("div",null,e[0]||(e[0]=[r('<h1 id="list-orders" tabindex="-1">List Orders <a class="header-anchor" href="#list-orders" aria-label="Permalink to &quot;List Orders&quot;">​</a></h1><p>Lists every order across all customers — the data behind the admin <strong>Sales → Orders</strong> screen.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>adminOrders</code></td><td>Query</td><td>Cursor-paginated list of all orders</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token in the <code>Authorization</code> header.</li><li><strong>Cursor pagination</strong> — pass <code>first</code> for the page size and <code>after</code> (the <code>endCursor</code> from the previous page) to advance. <code>pageInfo.hasNextPage</code> tells you when to stop; <code>totalCount</code> is the grand total.</li><li>Each <code>node</code> is a <strong>slim</strong> order row — flat fields only. Heavy relations (full items, invoices, shipments) are not embedded here; fetch a single order&#39;s detail for those.</li><li>The REST equivalent (<code>GET /api/admin/orders</code>) uses offset pagination with a <code>{ data, meta }</code> envelope instead of cursors.</li></ul><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><p>Pass any of these arguments alongside <code>first</code> / <code>after</code> to narrow the list (they mirror the admin datagrid filters):</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>order_id</code></td><td>Order increment ID — partial match</td></tr><tr><td><code>status</code></td><td><code>pending</code>, <code>pending_payment</code>, <code>processing</code>, <code>completed</code>, <code>canceled</code>, <code>closed</code>, <code>fraud</code></td></tr><tr><td><code>grand_total</code></td><td>Exact grand total (matched against the base grand total)</td></tr><tr><td><code>grand_total_from</code>, <code>grand_total_to</code></td><td>Grand total range (minimum / maximum)</td></tr><tr><td><code>channel</code></td><td>Channel ID</td></tr><tr><td><code>customer</code></td><td>Customer name — partial match</td></tr><tr><td><code>email</code></td><td>Customer email — partial match</td></tr><tr><td><code>date_range</code></td><td>Preset: <code>today</code>, <code>yesterday</code>, <code>this_week</code>, <code>this_month</code>, <code>last_month</code>, <code>last_three_months</code>, <code>last_six_months</code>, <code>this_year</code></td></tr><tr><td><code>date_from</code>, <code>date_to</code></td><td>Custom date range (<code>Y-m-d</code>) — overrides <code>date_range</code></td></tr><tr><td><code>sort</code>, <code>order</code></td><td>Sort field + <code>asc</code> / <code>desc</code> (default <code>created_at desc</code>)</td></tr></tbody></table>',9)]))}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
